mapper.select:
SELECT o.org_id, o.org_name, o.org_code, o.org_type, o.org_status, o.contact_phone, o.create_time, o.update_time, CASE o.org_type WHEN 1 THEN '公司' WHEN 2 THEN '部门' WHEN 3 THEN '小组' ELSE '未知' END as org_type_name FROM ${database.prefix.base}hou_base_organization o WHERE 1=1
AND o.org_id IN
#{orgId}
AND o.org_name LIKE CONCAT('%', #{dto.orgName}, '%')
AND o.org_code LIKE CONCAT('%', #{dto.orgCode}, '%')
AND o.org_type = #{dto.orgType}
AND o.parent_org_id = #{dto.parentOrgId}
AND o.org_status = #{dto.orgStatus}
ORDER BY o.create_time DESC

SELECT o.org_id, o.org_name, o.org_code, o.org_type, o.org_status, o.contact_phone, o.create_time, o.update_time FROM ${database.prefix.base}hou_base_organization o WHERE 1=1
AND o.org_id IN
#{orgId}
AND o.org_status = #{dto.orgStatus}
ORDER BY o.create_time ASC

SELECT COUNT(1)
FROM ${database.prefix.base}hou_base_organization
WHERE org_code = #{orgCode}

    AND org_id != #{orgId}

SELECT COUNT(1)
FROM ${database.prefix.base}hou_base_organization
WHERE org_name = #{orgName}

    AND org_id != #{orgId}
